-- ==========================================================================
-- Object      : SEC.MP_RESTRICTED_AMOUNT (masking policy)
-- Generated by: SemanticLift 1.0.0
-- Rules       : SEC-03
-- Confidence  : 1.00 (proposed)
-- Governance  : owner=Energy Data Engineering Team; classification=Restricted
-- ==========================================================================
CREATE MASKING POLICY IF NOT EXISTS SEC.MP_RESTRICTED_AMOUNT AS (v NUMBER) RETURNS NUMBER -> v
  COMMENT = 'Column grants (SEC.MAP_ROLE_GRANT keyed by ACCESS_GROUP tag) and ABAC deny rules (ABAC_POLICY tag)';

ALTER MASKING POLICY SEC.MP_RESTRICTED_AMOUNT SET BODY ->
    CASE
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',REGULATORY_SENSITIVE_DATA,') AND NOT (IS_ROLE_IN_SESSION('COMPLIANCE_OFFICERS') OR IS_ROLE_IN_SESSION('NERC_AUDITORS') OR IS_ROLE_IN_SESSION('REPORT_ADMINS')) THEN NULL
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',SENSITIVE_DATA_POLICY,') AND COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') = 'restricted' THEN NULL
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',SENSITIVE_FINANCIAL_DATA,') AND (COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') <> 'restricted' AND COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') <> 'confidential') THEN NULL
    WHEN SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ACCESS_GROUP') IS NULL THEN v
    WHEN EXISTS (SELECT 1 FROM SEC.MAP_ROLE_GRANT g WHERE g.ACCESS_GROUP = SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ACCESS_GROUP') AND g.GRANT_TYPE = 'DENY' AND IS_ROLE_IN_SESSION(g.ROLE_NAME)) THEN NULL
    WHEN EXISTS (SELECT 1 FROM SEC.MAP_ROLE_GRANT g WHERE g.ACCESS_GROUP = SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ACCESS_GROUP') AND g.GRANT_TYPE = 'ALLOW' AND IS_ROLE_IN_SESSION(g.ROLE_NAME)) THEN v
    ELSE NULL
    END;

ALTER MASKING POLICY SEC.MP_RESTRICTED_AMOUNT SET COMMENT = 'Column grants (SEC.MAP_ROLE_GRANT keyed by ACCESS_GROUP tag) and ABAC deny rules (ABAC_POLICY tag)';
